import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

# <<<IMPROVE:helpers>>>
_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p33_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor batch_norm_eval_forward_cuda(
    torch::Tensor x,
    torch::Tensor scale,
    torch::Tensor shift);

torch::Tensor batch_norm_eval_forward(
    torch::Tensor x,
    torch::Tensor scale,
    torch::Tensor shift) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(scale.is_cuda(), "scale must be a CUDA tensor");
    TORCH_CHECK(shift.is_cuda(), "shift must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (NCHW)");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(scale.dtype() == torch::kFloat32, "scale must be float32");
    TORCH_CHECK(shift.dtype() == torch::kFloat32, "shift must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(scale.is_contiguous(), "scale must be contiguous");
    TORCH_CHECK(shift.is_contiguous(), "shift must be contiguous");
    TORCH_CHECK(scale.size(0) == x.size(1), "scale length must equal C");
    TORCH_CHECK(shift.size(0) == x.size(1), "shift length must equal C");
    return batch_norm_eval_forward_cuda(x, scale, shift);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("batch_norm_eval_forward", &batch_norm_eval_forward, "BatchNorm eval forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void batch_norm_eval_kernel(
    const float* __restrict__ x,
    const float* __restrict__ scale,
    const float* __restrict__ shift,
    float* __restrict__ out,
    int N, int C, int H, int W) {
    int HW = H * W;
    int CHW = C * HW;
    int total = N * CHW;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;
    int c = (idx / HW) % C;
    out[idx] = x[idx] * scale[c] + shift[c];
}

torch::Tensor batch_norm_eval_forward_cuda(
    torch::Tensor x,
    torch::Tensor scale,
    torch::Tensor shift) {
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int total = N * C * H * W;
    auto out = torch::empty_like(x);
    int threads = 256;
    int blocks = (total + threads - 1) / threads;
    batch_norm_eval_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        scale.data_ptr<float>(),
        shift.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W);
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA kernel error: ", cudaGetErrorString(err));
    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs Batch Normalization.
        """
    def __init__(self, num_features: int):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the BatchNorm layer.

                Args:
                    num_features (int): Number of features in the input tensor.
                """
        self.bn = nn.BatchNorm2d(num_features=num_features)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        _use_custom = (
            not self.training
            and x.is_cuda
            and x.dim() == 4
            and x.dtype == torch.float32
            and x.is_contiguous()
            and self.bn.running_mean is not None
            and self.bn.running_var is not None
        )
        if _use_custom:
            inv_std = torch.rsqrt(self.bn.running_var + self.bn.eps)
            if self.bn.affine and self.bn.weight is not None and self.bn.bias is not None:
                scale = (inv_std * self.bn.weight).contiguous()
                shift = (self.bn.bias - self.bn.running_mean * scale).contiguous()
            else:
                scale = inv_std.contiguous()
                shift = (-self.bn.running_mean * inv_std).contiguous()
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if _use_custom:
            return _stark_get_extension().batch_norm_eval_forward(x, scale, shift)
        return self.bn(x)
        # <<<END_IMPROVE>>>
